import csv,statistics as s
r=list(csv.DictReader(open('daily.csv')))
import collections
d=collections.defaultdict(list)
for x in r: d[x['region']].append((x['date'],float(x['completion_time_seconds']),int(x['volume'])))
for g,v in d.items():
    print(g,len(v))
    for a,b in [('2026-02-01','2026-02-14'),('2026-02-15','2026-03-14'),('2026-03-01','2026-03-14'),('2026-03-15','2026-04-11')]:
        t=[c for dt,c,_ in v if a<=dt<=b]; print(' ',a,b,round(s.mean(t),1),round(s.median(t),1))
    # weekly means
    for i in range(0,len(v),7): print('  wk',v[i][0],round(s.mean(c for _,c,_ in v[i:i+7]),1))
